// Voice-over: one audio clip per narration line (the `subtitles` of each
// scene). Clips are generated by scripts/generate-voiceover.ts and listed in
// public/voiceover/manifest.json. This file is shared by the video and the
// generator script, so it must not import anything React / Remotion.
import type { VideoContent, VoiceClip } from "./schema";
import { buildTimeline } from "./timeline";

export const MANIFEST_PATH = "voiceover/manifest.json";

export type ManifestEntry = {
  file: string; // relative to public/
  text: string;
  durationInSeconds: number;
  provider: "elevenlabs" | "mock" | "recording";
  voiceId?: string;
  modelId?: string;
};

// videoId → line key (e.g. "tip2-1") → clip
export type VoiceManifest = Record<string, Record<string, ManifestEntry>>;

export type VoiceLine = {
  key: string;
  sceneIndex: number;
  lineIndex: number;
  text: string;
};

const sceneNames = (content: VideoContent) => [
  "intro",
  ...content.tips.map((_, i) => `tip${i + 1}`),
  "outro",
];

const sceneSubtitles = (content: VideoContent) => [
  content.intro.subtitles,
  ...content.tips.map((t) => t.subtitles),
  content.outro.subtitles,
];

export const getVoiceLines = (content: VideoContent): VoiceLine[] => {
  const names = sceneNames(content);
  return sceneSubtitles(content).flatMap((lines, sceneIndex) =>
    lines
      .map((text, lineIndex) => ({
        key: `${names[sceneIndex]}-${lineIndex}`,
        sceneIndex,
        lineIndex,
        text: text.trim(),
      }))
      .filter((line) => line.text.length > 0),
  );
};

const withSceneDurations = (content: VideoContent, durations: number[]): VideoContent => ({
  ...content,
  intro: { ...content.intro, durationInFrames: durations[0] },
  tips: content.tips.map((tip, i) => ({ ...tip, durationInFrames: durations[i + 1] })),
  outro: { ...content.outro, durationInFrames: durations[durations.length - 1] },
});

const TAIL = 6; // frames kept after the last line of a scene

// Frames between the start of a scene and its first narration line.
const leadIn = (sceneIndex: number, transition: number) =>
  sceneIndex === 0 ? 8 : Math.ceil(transition / 2) + 4;

/**
 * Places the voice clips on the timeline. A clip is used only if the manifest
 * text matches the current narration line (edited text = clip ignored until
 * it is regenerated). Scenes get longer if their narration needs more time.
 */
export const applyVoiceover = (
  content: VideoContent,
  entries: Record<string, ManifestEntry> | undefined,
  fps: number,
): VideoContent => {
  if (!content.voiceover.enabled || !entries) {
    return { ...content, voiceClips: [] };
  }

  const T = content.transitionDurationInFrames;
  const gap = content.voiceover.gapInFrames;
  const lines = getVoiceLines(content);
  const sceneCount = content.tips.length + 2;

  const relative: Omit<VoiceClip, "from">[] = [];
  const relativeFrom: number[] = [];
  const durations = sceneSubtitles(content).map((_, sceneIndex) => {
    const configured =
      sceneIndex === 0
        ? content.intro.durationInFrames
        : sceneIndex === sceneCount - 1
          ? content.outro.durationInFrames
          : content.tips[sceneIndex - 1].durationInFrames;

    let cursor = leadIn(sceneIndex, T);
    let hasClip = false;
    for (const line of lines.filter((l) => l.sceneIndex === sceneIndex)) {
      const entry = entries[line.key];
      if (!entry || entry.text.trim() !== line.text) {
        continue;
      }
      const durationInFrames = Math.ceil(
        (entry.durationInSeconds / content.voiceover.playbackRate) * fps,
      );
      relative.push({
        sceneIndex,
        lineIndex: line.lineIndex,
        src: entry.file,
        durationInFrames,
      });
      relativeFrom.push(cursor);
      cursor += durationInFrames + gap;
      hasClip = true;
    }
    if (!hasClip) {
      return configured;
    }
    const needed =
      cursor - gap + TAIL + (sceneIndex < sceneCount - 1 ? Math.ceil(T / 2) : 0);
    return Math.max(configured, needed);
  });

  const adjusted = withSceneDurations(content, durations);
  const timeline = buildTimeline(adjusted);
  const voiceClips = relative.map((clip, i) => ({
    ...clip,
    from: timeline[clip.sceneIndex].from + relativeFrom[i],
  }));
  return { ...adjusted, voiceClips };
};
